spring.application.name=global-payment-service

# Load-bearing, not a nicety: the app calls itself over HTTP to reach the
# stand-in FX provider, which a bounded thread pool can deadlock on. See
# docs/design-decisions.md 27-28.
spring.threads.virtual.enabled=true

# Every amount on the wire is a whole count of Minor Units. Jackson's default is to
# truncate a decimal into an integer field, which turns 100.50 euros into 100 cents with no
